Tool response:
Tool: search_flights
Description: Search for flights by flight number and tail number.
Parameters:
    {
      "type": "object",
      "properties": {
        "flight_number": {
          "type": "string",
          "description": "The flight number (e.g., FL-55802)",
          "title": "Flight Number"
        },
        "tail_number": {
          "type": "string",
          "description": "The aircraft tail number (e.g., N456EF)",
          "title": "Tail Number"
        }
      },
      "required": [
        "flight_number",
        "tail_number"
      ]
    }

